done = {}
def remote_start(vin, key):
    if key in done:
        return done[key] + " (이미 처리 — 다시 시동하지 않음)"
    done[key] = f"{vin} 시동 명령 1회 전송"
    return done[key]
print(remote_start("VIN00042", "a1b2"))
print(remote_start("VIN00042", "a1b2"))
